            $shortStock = $items->contains(fn ($item) => (float) $item->available < (float) $item->quantity);
        @endphp
        <details class="sales-quote" id="quote-{{ $quote->id }}">
            <summary class="sales-quote-summary"><span class="sales-quote-identity"><strong>{{ $quote->code }}</strong><small>{{ $quote->customer_name }}</small></span><span class="sales-quote-products">{{ $items->pluck('product_name')->implode(', ') ?: 'Chưa có vật liệu' }}</span><span class="sales-stock {{ $shortStock ? 'is-low' : 'is-ready' }}">{{ $shortStock ? 'Cần bổ sung' : 'Đủ tồn kho' }}</span><span class="sales-badge sales-badge--{{ $quote->status }}">{{ \App\Support\UiFormat::status($quote->status) }}</span><strong class="sales-quote-total">{{ number_format($quote->total, 0, ',', '.') }} ₫</strong><span class="sales-quote-open">Chi tiết <svg viewBox="0 0 16 16" aria-hidden="true"><path d="m3.5 6 4.5 4 4.5-4"/></svg></span></summary>
            <div class="sales-quote-detail">
                <section class="sales-detail-block"><h3>01 · Nhu cầu khách hàng</h3><dl class="sales-facts"><div><dt>Địa chỉ công trình</dt><dd>{{ $quote->delivery_address ?: 'Chưa cung cấp' }}</dd></div><div><dt>Ghi chú của khách</dt><dd>{{ $quote->customer_note ?: 'Không có' }}</dd></div></dl></section>
                <section class="sales-detail-block"><h3>02 · Vật liệu và tồn kho</h3><div class="table-responsive"><table class="table"><thead><tr><th>Vật liệu</th><th>Số lượng</th><th>Tổng tồn các kho</th><th>Đơn giá</th><th>Thành tiền</th></tr></thead><tbody>@foreach($items as $item)<tr><td>{{ $item->product_name }}</td><td>{{ \App\Support\UiFormat::quantity($item->quantity) }}</td><td class="{{ $item->available < $item->quantity ? 'text-danger' : '' }}">{{ \App\Support\UiFormat::quantity($item->available) }} @if($item->available < $item->quantity) · cần nhập thêm @endif</td><td>{{ number_format($item->unit_price, 0, ',', '.') }} ₫</td><td>{{ number_format($item->line_total, 0, ',', '.') }} ₫</td></tr>@endforeach</tbody></table></div></section>
