                <section class="sales-detail-block sales-detail-actions"><h3>03 · Lập và gửi báo giá</h3><form class="staff-quote-send-form" method="post" action="{{ route('staff.quotes.send', $quote->id) }}">@csrf<div class="row g-3">@foreach($items as $item)<div class="col-md-4"><label class="form-label">Đơn giá {{ $item->product_name }}<input class="form-control" type="number" min="0" step="0.01" name="prices[{{ $item->id }}]" value="{{ $item->unit_price }}" required></label></div>@endforeach<div class="col-md-4"><label class="form-label">Hiệu lực đến<input class="form-control" type="date" name="valid_until" min="{{ date('Y-m-d') }}" required></label></div>@if($shortStock)<div class="col-md-4"><label class="form-label">Dự kiến có hàng<input class="form-control" type="date" name="estimated_available_on" min="{{ date('Y-m-d') }}" value="{{ now()->addDays(14)->toDateString() }}" required></label></div><div class="col-md-8"><label class="form-label">Vật liệu thay thế đề xuất (nếu có)<input class="form-control" name="alternative_material" maxlength="1000" placeholder="Tên và quy cách vật liệu thay thế"></label></div>@endif</div><button class="btn btn-dark mt-3">Gửi báo giá</button></form><form class="sales-reject-form" method="post" action="{{ route('staff.quotes.reject', $quote->id) }}">@csrf<label class="form-label">Lý do từ chối<input class="form-control" name="reason" required></label><button class="btn btn-outline-danger">Từ chối</button></form></section>
                @endif
                @if($quote->status === 'pending_discount_approval' && auth()->user()->hasPermission('quotes.discount.review'))<section class="sales-detail-block sales-detail-actions"><h3>03 · Duyệt giá</h3><form method="post" action="{{ route('staff.quotes.discount-review', $quote->id) }}">@csrf<label class="form-label">Ý kiến<input class="form-control" name="note"></label><div class="sales-action-buttons"><button class="btn btn-dark" name="decision" value="approve">Duyệt giá</button><button class="btn btn-outline-danger" name="decision" value="reject">Yêu cầu sửa</button></div></form></section>@endif
